macro_rules! filename_and_frag_for_def {
    () => {
        # [doc = " Get the filename and extension generated for a symbol by rustdoc."] # [doc = ""] # [doc = " ```ignore"] # [doc = " https://doc.rust-lang.org/std/iter/trait.Iterator.html#tymethod.next"] # [doc = "                                    ^^^^^^^^^^^^^^^^^^^"] # [doc = " ```"] fn filename_and_frag_for_def (db : & dyn HirDatabase , def : Definition ,) -> Option < (Definition , String , Option < String >) > { if let Some (assoc_item) = def . as_assoc_item (db) { let def = match assoc_item . container (db) { AssocItemContainer :: Trait (t) => t . into () , AssocItemContainer :: Impl (i) => i . self_ty (db) . as_adt () ? . into () , } ; let (_ , file , _) = filename_and_frag_for_def (db , def) ? ; let frag = get_assoc_item_fragment (db , assoc_item) ? ; return Some ((def , file , Some (frag))) ; } let res = match def { Definition :: Adt (adt) => match adt { Adt :: Struct (s) => { format ! ("struct.{}.html" , s . name (db) . as_str ()) } Adt :: Enum (e) => format ! ("enum.{}.html" , e . name (db) . as_str ()) , Adt :: Union (u) => format ! ("union.{}.html" , u . name (db) . as_str ()) , } , Definition :: Crate (_) => String :: from ("index.html") , Definition :: Module (m) => match m . name (db) { Some (name) => { match m . attrs (db) . by_key (sym :: doc) . find_string_value_in_tt (sym :: keyword) { Some (kw) => { format ! ("keyword.{kw}.html") } None => format ! ("{}/index.html" , name . as_str ()) , } } None => String :: from ("index.html") , } , Definition :: Trait (t) => { format ! ("trait.{}.html" , t . name (db) . as_str ()) } Definition :: TypeAlias (t) => { format ! ("type.{}.html" , t . name (db) . as_str ()) } Definition :: BuiltinType (t) => { format ! ("primitive.{}.html" , t . name () . as_str ()) } Definition :: Function (f) => { format ! ("fn.{}.html" , f . name (db) . as_str ()) } Definition :: Variant (ev) => { let def = Definition :: Adt (ev . parent_enum (db) . into ()) ; let (_ , file , _) = filename_and_frag_for_def (db , def) ? ; return Some ((def , file , Some (format ! ("variant.{}" , ev . name (db) . as_str ())))) ; } Definition :: Const (c) => { format ! ("constant.{}.html" , c . name (db) ?. as_str ()) } Definition :: Static (s) => { format ! ("static.{}.html" , s . name (db) . as_str ()) } Definition :: Macro (mac) => match mac . kind (db) { hir :: MacroKind :: Declarative | hir :: MacroKind :: AttrBuiltIn | hir :: MacroKind :: DeclarativeBuiltIn | hir :: MacroKind :: Attr | hir :: MacroKind :: ProcMacro => { format ! ("macro.{}.html" , mac . name (db) . as_str ()) } hir :: MacroKind :: Derive | hir :: MacroKind :: DeriveBuiltIn => { format ! ("derive.{}.html" , mac . name (db) . as_str ()) } } , Definition :: Field (field) => { let def = match field . parent_def (db) { hir :: VariantDef :: Struct (it) => Definition :: Adt (it . into ()) , hir :: VariantDef :: Union (it) => Definition :: Adt (it . into ()) , hir :: VariantDef :: Variant (it) => Definition :: Variant (it) , } ; let (_ , file , _) = filename_and_frag_for_def (db , def) ? ; return Some ((def , file , Some (format ! ("structfield.{}" , field . name (db) . as_str ())))) ; } Definition :: SelfType (impl_) => { let adt = impl_ . self_ty (db) . as_adt () ? . into () ; let (_ , file , _) = filename_and_frag_for_def (db , adt) ? ; return Some ((adt , file , Some (String :: from ("impl")))) ; } Definition :: ExternCrateDecl (it) => { format ! ("{}/index.html" , it . name (db) . as_str ()) } Definition :: Local (_) | Definition :: GenericParam (_) | Definition :: TupleField (_) | Definition :: Label (_) | Definition :: BuiltinAttr (_) | Definition :: BuiltinLifetime (_) | Definition :: ToolModule (_) | Definition :: DeriveHelper (_) | Definition :: InlineAsmRegOrRegClass (_) | Definition :: InlineAsmOperand (_) => return None , } ; Some ((def , res , None)) }
    };
}

filename_and_frag_for_def!()